#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr = NULL;
    errno = 0;
    long n = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0' || errno == ERANGE) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n > 1000000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    if (n < 2) {
        puts("NONE");
        return 0;
    }
    long original = n;
    int first = 1;
    for (long p = 2; p * p <= n; ++p) {
        if (n % p == 0) {
            int exp = 0;
            while (n % p == 0) {
                n /= p;
                ++exp;
            }
            if (!first) putchar(' ');
            printf("%ld^%d", p, exp);
            first = 0;
        }
    }
    if (n > 1) {
        if (!first) putchar(' ');
        printf("%ld^1", n);
    }
    putchar('\n');
    return 0;
}
